### Step 2: StreakEngine.swift

```swift
// Domain/StreakEngine.swift

import Foundation

struct StreakEngine {

    func computeStreak(from dayStates: [DayState]) -> Int {
        var streak = 0
        for i in stride(from: dayStates.count - 1, through: 0, by: -1) {
            if dayStates[i].hasCheckedInToday {
                streak += 1
            } else {
                break
            }
        }
        return streak
    }
}

// Unit Tests for StreakEngine

import XCTest

class StreakEngineTests: XCTestCase {

    func testStreakWithAllCheckIns() {
        let dayStates = [
            DayState(dateKey: "2023-10-01", hasCheckedInToday: true),
            DayState(dateKey: "2023-10-02", hasCheckedInToday: true),
            DayState(dateKey: "2023-10-03", hasCheckedInToday: true)
        ]
        let streakEngine = StreakEngine()
        XCTAssertEqual(streakEngine.computeStreak(from: dayStates), 3)
    }

    func testStreakWithBreaks() {
        let dayStates = [
            DayState(dateKey: "2023-10-01", hasCheckedInToday: true),
            DayState(dateKey: "2023-10-02", hasCheckedInToday: false),
            DayState(dateKey: "2023-10-03", hasCheckedInToday: true)
        ]
        let streakEngine = StreakEngine()
        XCTAssertEqual(streakEngine.computeStreak(from: dayStates), 1)
    }

    func testNoCheckIns() {
        let dayStates: [DayState] = []
        let streakEngine = StreakEngine()
        XCTAssertEqual(streakEngine.computeStreak(from: dayStates), 0)
    }
}
```

